<script setup lang="ts">
import {ref,watch,computed} from 'vue'
import {NButton,NInput,NModal,NSelect} from 'naive-ui'
import {money,type Account} from '../api/funds'
import {membersApi,type Member,type Claim,type RepaymentInput,type RepaymentPreview,type Allocation} from '../api/memberClaims'
import EndpointSelector from './EndpointSelector.vue'
const props=defineProps<{show:boolean;member:Member;accounts:Account[];claims:Claim[]}>()
const emit=defineEmits<{close:[];saved:[]}>()
const fresh=():RepaymentInput=>({member_id:props.member.id,source_account_id:'',amount:'',effective_date:new Date().toLocaleDateString('sv-SE'),description:'',basis:'',allocation_mode:'oldest_first'})
const form=ref(fresh()),manual=ref<Record<string,string>>({}),preview=ref<RepaymentPreview|null>(null),busy=ref(false),error=ref(''),key=ref(''),stamp=ref(''),submitted=ref<(RepaymentInput&{allocations:Allocation[];idempotency_key:string})|null>(null)
const input=computed<RepaymentInput>(()=>({...form.value,...form.value.allocation_mode==='manual'?{allocations:Object.entries(manual.value).filter(([,amount])=>amount.trim()).map(([claim_id,amount])=>({claim_id,amount}))}:{}}))
const valid=computed(()=>preview.value&&stamp.value===JSON.stringify(input.value))
watch(input,()=>{preview.value=null},{deep:true})
watch(()=>props.show,show=>{if(show&&!submitted.value){form.value=fresh();manual.value={};preview.value=null;key.value='';error.value=''}})
async function runPreview(){if(busy.value||submitted.value)return;busy.value=true;error.value='';preview.value=null;const payload=JSON.parse(JSON.stringify(input.value)),current=JSON.stringify(payload);try{const result=await membersApi.preview(payload);if(JSON.stringify(input.value)===current){preview.value=result;stamp.value=current;key.value=''}}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function save(){if(busy.value||(!submitted.value&&!valid.value))return;busy.value=true;error.value='';if(!submitted.value){key.value ||= crypto.randomUUID();submitted.value={...JSON.parse(JSON.stringify(input.value)),allocations:JSON.parse(JSON.stringify(preview.value!.allocations)),idempotency_key:key.value}}try{await membersApi.submitRepayment(submitted.value!);submitted.value=null;emit('saved');emit('close')}catch(e){const failure=e as Error&{status?:number};if(failure.status===409&&failure.message.includes('重新预览')){submitted.value=null;preview.value=null;key.value='';error.value=failure.message+'。旧匹配已失效，请重新预览。'}else{error.value=failure.message+'。请先查询已存记录；重试使用相同内容和标识。'}}finally{busy.value=false}}
function reset(){submitted.value=null;preview.value=null;key.value='';error.value='请核对已存记录后重新预览。'}
</script>
<template><NModal :show="show" preset="card" title="偿还成员垫付" class="dialog" @close="emit('close')"><p>收款成员：{{member.name}}（{{member.account_id}}）</p><EndpointSelector v-model="form.source_account_id" :accounts="accounts.filter(a=>a.is_fund)" label="付款资金账户" :disabled="!!submitted||busy"/><label>付款金额（元）<NInput v-model:value="form.amount" :disabled="!!submitted||busy"/></label><label>业务日期<input v-model="form.effective_date" type="date" :disabled="!!submitted||busy"></label><label>付款依据<NInput v-model:value="form.basis" :disabled="!!submitted||busy"/></label><label>说明<NInput v-model:value="form.description" :disabled="!!submitted||busy"/></label><label>匹配方式<NSelect v-model:value="form.allocation_mode" :disabled="!!submitted||busy" :options="[{label:'按确认时间先后匹配',value:'oldest_first'},{label:'手动指定每笔金额',value:'manual'}]"/></label><template v-if="form.allocation_mode==='manual'"><label v-for="claim in claims.filter(c=>c.outstanding_minor>0)" :key="claim.id">{{claim.transfer.effective_date}}，未结 ¥{{money(claim.outstanding_minor)}}（{{claim.id}}）<NInput :value="manual[claim.id]||''" :disabled="!!submitted||busy" placeholder="本次偿还金额（元），留空不匹配" @update:value="manual[claim.id]=$event"/></label></template><div v-if="preview" class="preview"><strong>付款 ¥{{money(preview.amount_minor)}}，资金账户减少相同金额</strong><table><thead><tr><th>垫付编号</th><th>本次匹配（元）</th><th>版本</th></tr></thead><tbody><tr v-for="a in preview.allocations" :key="a.claim_id"><td>{{a.claim_id}}</td><td>{{a.amount}}</td><td>{{a.expected_version}}</td></tr></tbody></table></div><p v-if="error" class="error">{{error}}</p><small v-if="key">提交标识：{{key}}；重试保留本次预览与完整付款内容。</small><div class="actions"><NButton :disabled="!!submitted" :loading="busy" @click="runPreview">预览匹配</NButton><NButton type="primary" :disabled="!submitted&&!valid" :loading="busy" @click="save">{{submitted?'使用相同标识重试':'确认付款'}}</NButton><NButton v-if="submitted" :disabled="busy" @click="reset">已核对记录，重新预览</NButton></div></NModal></template>
